 static VoxelShape get(String kind,BlockState state){if(!BASE.containsKey(kind))return null;return CACHE.computeIfAbsent(state,s->{var source=BASE.get(kind);boolean vertical=s.hasProperty(SteamTurbine.Part.VERTICAL)&&s.getValue(SteamTurbine.Part.VERTICAL)&&Set.of("turbine_shaft","turbine_blade","turbine_bearing").contains(kind);int turns=switch(NuclearPart.facing(s)){case EAST->1;case SOUTH->2;case WEST->3;default->0;};VoxelShape out=Shapes.empty();for(var b:source.toAabbs()){double x0=b.minX,y0=b.minY,z0=b.minZ,x1=b.maxX,y1=b.maxY,z1=b.maxZ;if(vertical){double a=y0,c=y1;y0=1-z1;y1=1-z0;z0=a;z1=c;}for(int i=0;i<turns;i++){double a=x0,c=x1;x0=1-z1;x1=1-z0;z0=a;z1=c;}out=Shapes.or(out,Shapes.box(x0,y0,z0,x1,y1,z1));}return out.optimize();});}
